function initCloud(){
 cloudController?.stop();
 cloudController=createSyncController({config:syncConfig,getProgress:()=>state,getBank:()=>bank,blankProgress:blank,
  setProgress:(next,{accountChanged=false}={})=>{
   let safe;try{safe=validateBackup({version:4,...next},bank);}catch{return false;}
   const previous=state;state=safe;if(!persistProgress()){state=previous;return false;}
   if(accountChanged){hostDialogue.pause();hostGame=blankHostGame();saveHost();clearVoice();gameClockPending=0;practice=null;cards=null;storeSession('practice');storeSession('cards');duelEpoch++;duelBusy=false;duelTurn=null;duelList=[];}
   applyTheme();
   if(loadReady&&(accountChanged||['home','progress'].includes(view)||(view==='play'&&ui.playLobby)||(view==='account'&&!accountBusy)))render();
   return true;
  },
  onStatus:status=>{
   const previous=syncStatus.user?.id;syncStatus=status;
   if(previous!==status.user?.id){duelEpoch++;duelBusy=false;duelTurn=null;duelList=[];duelError='';if(loadReady&&view==='duel')render();}
   refreshSyncLabels();
   if(loadReady&&view==='account'&&!accountBusy&&(status.user||previous))render();
  }
 });
 void cloudController.init();
}
