 if(mode==='duel'){await createFriendDuel(selected,limit);return;}
 try{state.frenzy=startFrenzy({...state.frenzy||blankFrenzy(),active:null},arcadePool('frenzy'),{topics:selected,limit,now:Date.now(),seed:Math.random(),runId:'frenzy-'+(globalThis.crypto?.randomUUID?.()||Date.now().toString(36)+'-'+Math.random().toString(36).slice(2))});save();navigate('frenzy');}catch{toast('This round could not start. Choose subjects again.');}
