function frenzyQuestion(){const a=state.frenzy?.active;return a?byId.get(a.queue[a.index]?.id):null;}
function frenzyView(){const q=frenzyQuestion();return renderFrenzy({progress:state.frenzy||blankFrenzy(),q,voiceHTML:voicePanel('choice'),lessonHTML:q?lesson(q,'arcade'):''});}
function recordGameEvent(q,correct,at,eventId){
 if(!q||state.log.some(e=>e.eventId===eventId))return;
 const old=state.records[q.id]||{};
 let next=at>=(old.reviewedAt||0)?schedule(old,correct?'good':'again',at):{...old,reviews:(old.reviews||0)+1};
 if(at>=(old.lastGameAt||0))next={...next,lastGameCorrect:correct,lastGameAt:at};
 state.records[q.id]=next;state.log.push({id:q.id,correct,at,kind:'game',eventId});
}
function frenzyAnswer(choice){
 const old=state.frenzy?.active;if(!old||old.phase!=='question')return;
 try{
  const next=answerFrenzy(state.frenzy,bank,choice,{now:Date.now()});
  if(next.active.responses.length===old.responses.length)return;
  if(view==='frenzy')clearVoice();state.frenzy=next;const response=next.active.responses.at(-1);
  recordGameEvent(byId.get(response.id),response.correct,response.at,`frenzy:${next.active.id}:${next.active.index}`);save();
  if(view==='frenzy'){render();window.scrollTo(0,0);$('.arcade-feedback')?.focus({preventScroll:true});}
 }catch{toast('Your round is saved. Reopen Frenzy to continue.');}
}
